parameters.jsCode:
const lead = $('Validate Lead').first().json;
const raw = $json.message?.content ?? $json.content ?? $json.text ?? '';
if (!raw) throw new Error('AI response was empty');
const cleaned = String(raw).trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '');
let analysis;
try { analysis = JSON.parse(cleaned); } catch { throw new Error('AI returned invalid JSON: ' + cleaned); }
if (typeof analysis.qualified !== 'boolean') throw new Error('AI qualified field must be boolean');
const score = Number(analysis.score);
if (!Number.isFinite(score) || score < 0 || score > 100) throw new Error('AI score must be between 0 and 100');
const priority = String(analysis.priority ?? '').toLowerCase();
if (!['high','medium','low'].includes(priority)) throw new Error('AI priority must be high, medium, or low');
return [{ json: { ...lead, qualified: analysis.qualified, score, priority, reason: String(analysis.reason ?? ''), service_needed: String(analysis.service_needed ?? ''), recommended_action: String(analysis.recommended_action ?? ''), status: analysis.qualified ? 'Qualified' : 'Nurture' } }];

